/// <summary>
/// MPJ_2677 - Kscerri - 26/05/2021
/// The <c>METPurchReqTableFormEventHandler</c> class for event handlers
/// </summary>
class METPurchReqTableFormEventHandler
{
}

Method.Source:
    /// <summary>
    /// MPJ_2677 - Kscerri - 27/05/2021
    /// </summary>
    /// <param name="sender"> form control</param>
    /// <param name="e"> form event</param>
    [
        FormControlEventHandler(formControlStr(PurchReqTable, PurchReqTable_METCustAcc), FormControlEventType::Modified),
        SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface')
    ]
    public static void PurchReqTable_METCustAcc_OnModified(FormControl sender, FormControlEventArgs e)
    {
        FormRun         form                = sender.formRun();
        FormDataSource  PurchReqTable_ds   = form.dataSource(formDataSourceStr(PurchReqTable, PurchReqtable)) as FormDataSource;
        PurchReqTable   purchReqTable       = PurchReqTable_ds.cursor();

        purchReqTable.METCustName = purchReqTable.getCustName(purchReqTable.METCustAcc);
        PurchReqTable_ds.refresh();
    }

    /// <summary>
    /// MPJ_2677 - Kscerri - 27/05/2021
    /// </summary>
    /// <param name="sender"> form control</param>
    /// <param name="e"> form event</param>
    [
        FormDataFieldEventHandler(formDataFieldStr(PurchReqTable, PurchReqTable, BusinessJustification), FormDataFieldEventType::Modified),
        SuppressBPWarningAttribute('BPParameterNotUsed', 'Parameter required by the event interface')
    ]
    public static void BusinessJustification_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        FormDataSource PurchReqTable_ds  = sender.datasource();
        PurchReqTable  purchReqTable     = PurchReqTable_ds.cursor();
        PurchParameters purchParameters = PurchParameters::find();        

        if (purchParameters.METPRReason == purchReqTable.BusinessJustification)
        {
            PurchReqTable_ds.object(fieldNum(PurchReqTable,METCustAcc)).mandatory(true);
        }
        else
        {
            PurchReqTable_ds.object(fieldNum(PurchReqTable,METCustAcc)).mandatory(false);
        }

    }
